//! The workspace-local bindings generator.
//!
//! UniFFI ships no system-wide binary on purpose: bindings generated by a
//! different version than the `uniffi` the library links carry different
//! checksums, and the mismatch surfaces as a load-time failure in the app
//! rather than a build error. Building the generator out of this crate's own
//! dependency graph makes the two versions the same one by construction.

fn main() {
    uniffi::uniffi_bindgen_main()
}
